uniform float density : 0.0 .. 1.0 = 0.03;
uniform float speed   : 0.0 .. 5.0 = 0.8;
uniform float size    : 0.0 .. 0.5 = 0.15;
uniform vec3  tint    : color = 1.0, 0.95, 0.85;
uniform vec3  bg      : color = 0.02, 0.02, 0.05;

state fixed phase;

void update() {
  phase = fract(phase + fixed(dt * speed));
}

vec3 shade(Led led) {
  fixed s  = fixed(led.s);
  fixed id = fixed(float(led.idx));

  fixed h1 = fract(id * fixed(0.618034) + phase * fixed(7.0));
  fixed h2 = fract(id * fixed(1.618034) + phase * fixed(11.0));

  fixed twinkle = h1 * h2;
  fixed on = step(fixed(1.0) - fixed(density), twinkle);

  fixed d = abs(s - h1);
  fixed pulse = sin(twinkle * fixed(6.2832));
  fixed envelope = clamp(fixed(1.0) - d * fixed(1.0) / fixed(size), fixed(0.0), fixed(1.0));
  fixed brightness = on * envelope * (fixed(0.3) + fixed(0.7) * (fixed(1.0) + pulse) * fixed(0.5));

  return tint * float(brightness) + bg;
}
